{
  "fields": [
    {
      "id": "space_count",
      "value": 36,
      "evidence": "Rent-Roll.xlsx!Rent Roll C7:C42 (units 101–136)",
      "calculation": "Count of listed units 101–136 = 36"
    },
    {
      "id": "occupied_count",
      "value": 33,
      "evidence": "Rent-Roll.xlsx!Rent Roll F7:F42 (Status); Vacant at 109, 125, 136",
      "calculation": "36 total - 3 vacant = 33 occupied"
    },
    {
      "id": "total_area_sf",
      "value": 31800,
      "evidence": "Rent-Roll.xlsx!Rent Roll E7:E42 (Area SF)",
      "calculation": "20 units × 750 sf + 16 units × 1,050 sf = 15,000 + 16,800 = 31,800 sf"
    },
    {
      "id": "occupied_area_sf",
      "value": 28950,
      "evidence": "Rent-Roll.xlsx!Rent Roll rows with Status='Occupied'",
      "calculation": "Occupied: 19 units × 750 sf + 14 units × 1,050 sf = 14,250 + 14,700 = 28,950 sf"
    },
    {
      "id": "occupancy_count_pct",
      "value": 91.67,
      "evidence": "Derived from space_count and occupied_count",
      "calculation": "33 / 36 = 0.9167 → 91.67%"
    },
    {
      "id": "occupancy_area_pct",
      "value": 91.04,
      "evidence": "Derived from total_area_sf and occupied_area_sf",
      "calculation": "28,950 / 31,800 = 0.9104 → 91.04%"
    },
    {
      "id": "rent_roll_monthly_base",
      "value": 62275,
      "evidence": "Rent-Roll.xlsx!Rent Roll G7:G42; blanks for vacant (C45 note)",
      "calculation": "750-sf occupied: 19 × $1,675 = $31,825; 1,050-sf occupied: 14 × $2,175 = $30,450; total = $62,275"
    },
    {
      "id": "effective_monthly_base",
      "value": 62275,
      "evidence": "Lease-File.pdf p.1 §3 (Unit 101 $1,675/mo; no increases before 2027-09-01). No other signed amendments supplied.",
      "calculation": "No authoritative amendments provided aside from unit 101 confirming $1,675; therefore effective equals printed rent roll for all units = $62,275"
    },
    {
      "id": "t12_egi",
      "value": 821100,
      "evidence": "T12-Statement.pdf p.2 (Annual totals)",
      "calculation": "Gross potential $840,000 - vacancy $42,000 - concessions $12,000 - bad debt $4,500 + other income $39,600 = $821,100"
    },
    {
      "id": "t12_operating_expenses",
      "value": 307800,
      "evidence": "T12-Statement.pdf p.2 (Annual totals)",
      "calculation": "Taxes 108,000 + Insurance 31,200 + Utilities 28,800 + R&M 46,200 + Payroll 42,000 + Admin 21,600 + Mgmt 30,000 = $307,800"
    },
    {
      "id": "t12_noi_before_reserves",
      "value": 513300,
      "evidence": "Derived from T12-Statement.pdf p.2",
      "calculation": "EGI $821,100 - OpEx $307,800 = $513,300"
    },
    {
      "id": "t12_reserves",
      "value": 10800,
      "evidence": "T12-Statement.pdf p.2 (Replacement reserves annual total)",
      "calculation": "Sum of monthly replacement reserves = $10,800"
    },
    {
      "id": "t12_ncf",
      "value": 502500,
      "evidence": "Derived from T12-Statement.pdf p.2",
      "calculation": "NOI before reserves $513,300 - reserves $10,800 = $502,500"
    },
    {
      "id": "uw_egi",
      "value": 854160,
      "evidence": "Property-and-Plan.pdf p.2 (Underwriting plan)",
      "calculation": "GPBR $864,000 - 6.0% loss $51,840 + other income $42,000 = $854,160"
    },
    {
      "id": "uw_management_fee",
      "value": 30000,
      "evidence": "Property-and-Plan.pdf p.2 (Management fee rule and T12 actual $30,000)",
      "calculation": "Greater of T12 actual $30,000 and 3% of EGI (3% × $854,160 = $25,624.80) → $30,000"
    },
    {
      "id": "uw_operating_expenses",
      "value": 308200,
      "evidence": "Property-and-Plan.pdf p.2 (category-by-category instructions)",
      "calculation": "Taxes 112,000 + Insurance 33,600 + Utilities 28,800 + R&M (46,200 - 6,000 one-time) 40,200 + Payroll 42,000 + Admin 21,600 + Mgmt 30,000 = $308,200"
    },
    {
      "id": "uw_noi_before_reserves",
      "value": 545960,
      "evidence": "Derived from Property-and-Plan.pdf p.2",
      "calculation": "EGI $854,160 - OpEx $308,200 = $545,960"
    },
    {
      "id": "uw_reserves",
      "value": 10800,
      "evidence": "Property-and-Plan.pdf p.2 (Replacement reserves $300/unit/year); Rent-Roll.xlsx (36 units)",
      "calculation": "36 units × $300 = $10,800"
    },
    {
      "id": "uw_ncf",
      "value": 535160,
      "evidence": "Derived from underwriting above",
      "calculation": "NOI before reserves $545,960 - reserves $10,800 = $535,160"
    },
    {
      "id": "capitalization_value",
      "value": 9494956.52,
      "evidence": "Lender-Terms.pdf p.1 (Value = UW NOI before reserves / 5.75% cap)",
      "calculation": "$545,960 / 0.0575 = $9,494,956.52"
    },
    {
      "id": "contract_rate",
      "value": 0.059,
      "evidence": "Lender-Terms.pdf p.1 (Contract rate 5.90% fixed)",
      "calculation": "As stated"
    },
    {
      "id": "sizing_rate",
      "value": 0.0625,
      "evidence": "Lender-Terms.pdf p.1 (Greater of contract 5.90% and 6.25% floor → 6.25%)",
      "calculation": "max(0.0590, 0.0625) = 0.0625"
    },
    {
      "id": "annual_debt_constant",
      "value": 0.073908,
      "evidence": "Lender-Terms.pdf p.1 (30-year, monthly payments; sizing rate 6.25%)",
      "calculation": "12 × [r_m / (1 - (1 + r_m)^-360)], r_m = 0.0625/12 = 0.0052083333 → annual constant ≈ 0.073908"
    },
    {
      "id": "ltv_limit",
      "value": 6171721.74,
      "evidence": "Lender-Terms.pdf p.1 (LTV 65%; valuation NOI/5.75%)",
      "calculation": "65% × $9,494,956.52 = $6,171,721.74"
    },
    {
      "id": "dscr_limit",
      "value": 5792651.00,
      "evidence": "Lender-Terms.pdf p.1 (DSCR ≥1.25 with NCF/annual amortizing debt service at sizing rate)",
      "calculation": "Allowable DS = $535,160 / 1.25 = $428,128; Loan = $428,128 / 0.073908 ≈ $5,792,651"
    },
    {
      "id": "debt_yield_limit",
      "value": 6296000,
      "evidence": "Lender-Terms.pdf p.1 (Debt yield ≥8.50%; numerator UW NCF after reserves)",
      "calculation": "$535,160 / 0.085 = $6,296,000"
    },
    {
      "id": "maximum_loan",
      "value": 5792651.00,
      "evidence": "Lender-Terms.pdf p.1 (Loan ceiling is lowest of three constraints)",
      "calculation": "min(LTV $6.172M, DSCR $5.793M, Debt Yield $6.296M) = $5.793M (DSCR)"
    },
    {
      "id": "binding_constraint",
      "value": "DSCR",
      "evidence": "See constraint calculations above",
      "calculation": "DSCR limit is the smallest"
    },
    {
      "id": "sizing_annual_debt_service",
      "value": 428128.00,
      "evidence": "Derived from maximum_loan and annual_debt_constant",
      "calculation": "$5,792,651 × 0.073908 ≈ $428,128"
    },
    {
      "id": "sizing_dscr",
      "value": 1.25,
      "evidence": "Lender DSCR convention",
      "calculation": "$535,160 / $428,128 = 1.25x"
    },
    {
      "id": "sizing_debt_yield",
      "value": 0.0924,
      "evidence": "Lender debt yield convention (UW NCF / Loan)",
      "calculation": "$535,160 ÷ $5,792,651 ≈ 0.0924 (9.24%)"
    },
    {
      "id": "first_year_debt_service",
      "value": 341766.41,
      "evidence": "Lender-Terms.pdf p.1 (24 months interest-only; contract rate 5.90%)",
      "calculation": "Year 1 IO interest = $5,792,651 × 0.0590 = $341,766.41"
    },
    {
      "id": "cash_to_borrower",
      "value": 2404206.12,
      "evidence": "Property-and-Plan.pdf p.1 (Existing payoff $3,300,000; Fixed closing costs $45,000); Lender-Terms.pdf p.1 (Origination fee 0.75%)",
      "calculation": "$5,792,651 - $3,300,000 - (0.75% × $5,792,651 = $43,444.88) - $45,000 = $2,404,206.12"
    },
    {
      "id": "stress_uw_noi",
      "value": 503252.00,
      "evidence": "Property-and-Plan.pdf p.2 (Sensitivity instruction)",
      "calculation": "Stress EGI = $854,160 × 95% = $811,452; Mgmt = max($30,000, 3% × $811,452 = $24,343.56) → $30,000; Other OpEx unchanged ($278,200 excl. mgmt). Stress OpEx = $308,200. Stress NOI (before reserves) = $811,452 - $308,200 = $503,252"
    },
    {
      "id": "stress_maximum_loan",
      "value": 4810354.00,
      "evidence": "Property-and-Plan.pdf p.2 (Sensitivity instruction: EGI -5%, sizing rate +100 bps, cap rate unchanged); Lender-Terms.pdf p.1",
      "calculation": "Stress NCF = ($503,252 - $10,800) = $492,452; Sizing rate = 7.25% (floor +100 bps); 30-yr annual constant ≈ 0.08190; DSCR-limit loan = ($492,452 / 1.25) / 0.08190 ≈ $4,810,354. LTV-limit (65% × [$503,252/0.0575]) ≈ $5,688,936; Debt-yield limit ($492,452/0.085) ≈ $5,793,553. Minimum = DSCR ≈ $4.81M"
    },
    {
      "id": "subject_lease_monthly_rent",
      "value": 1675,
      "evidence": "Lease-File.pdf p.1 §3; Rent-Roll.xlsx!Rent Roll G7 (unit 101)",
      "calculation": "As stated in executed lease extract; matches rent roll"
    },
    {
      "id": "subject_lease_expiry",
      "value": "2027-07-31",
      "evidence": "Lease-File.pdf p.1 §2; Rent-Roll.xlsx!Rent Roll I7",
      "calculation": "As stated; no renewal exercise delivered"
    },
    {
      "id": "subject_lease_deposit",
      "value": 1675,
      "evidence": "Lease-File.pdf p.1 §4",
      "calculation": "As stated"
    },
    {
      "id": "verified_renewal_insurance",
      "value": 33600,
      "evidence": "Property-and-Plan.pdf p.2 (Insurance evidence: renewal premium $33,600; use in underwriting)",
      "calculation": "As stated"
    },
    {
      "id": "renewal_option_exercised",
      "value": false,
      "evidence": "Lease-File.pdf p.1 §5 (No exercise notice included; do not extend expiry based on option alone)",
      "calculation": "No evidence of exercise in packet"
    },
    {
      "id": "prepayment_friction",
      "value": "1% of outstanding principal if prepaid in years 1–2; no stated bank penalty thereafter; no swap assumed.",
      "evidence": "Lender-Terms.pdf p.1 (Prepayment section)",
      "calculation": "As stated"
    }
  ],
  "qualifications": [
    "All analyses are based solely on the provided packet as of 2026-08-31; no external data, geocoding, market comps or outreach were used.",
    "Displayed currency is rounded for readability; lender sizing logic uses unrounded intermediate values per the term sheet.",
    "Annual debt service constants are computed via the standard monthly amortization formula; minor rounding differences may occur absent a spreadsheet.",
    "Only unit 101 has an executed lease extract; for other units, effective contractual rent is taken as printed on the rent roll due to no conflicting signed amendments provided.",
    "Historical T12 presentation includes items below NOI (reserves, capital improvements, debt service, depreciation); these are excluded from operating expenses and NOI per instructions.",
    "Vacant-unit market rents on the rent roll are contextual and not treated as collected income.",
    "Management fee follows the stated underwriting rule: greater of T12 actual ($30,000) and 3.00% of underwritten/stressed EGI.",
    "Sensitivity per instructions: EGI reduced by 5% and sizing rate increased by 100 bps; other operating expenses and reserves held constant; cap rate unchanged.",
    "This control cannot deliver files (XLSX workbook or PDF memo); see blocked items."
  ],
  "summary": "Juniper Flats underwriting and sizing as of 2026-08-31 are complete from the packet. Rent roll shows 36 units (31,800 sf), 33 occupied, with physical occupancy of 91.67% by count and 91.04% by area. Monthly base rent printed is $62,275 and matches the executed lease for unit 101 ($1,675/mo; expiry 2027-07-31; $1,675 deposit; no renewal exercise evidence). T12 actuals (Sep-2025 to Aug-2026) produce EGI $821,100, operating expenses $307,800, NOI before reserves $513,300, reserves $10,800, and NCF $502,500. Underwriting per the plan yields EGI $854,160, operating expenses $308,200 (incl. management fee at the $30,000 T12 level), NOI before reserves $545,960, reserves $10,800, and NCF $535,160. Using the 5.75% cap on UW NOI before reserves indicates a value of approximately $9.495 million. Lender sizing at a 6.25% underwriting rate and 30-year amortization gives an annual debt constant of ~7.3908%. Constraints are: LTV limit ~$6.172M, DSCR limit ~$5.793M (binding), and debt yield limit ~$6.296M, so the maximum loan is ~$5.793M. The sizing annual amortizing debt service at this loan is ~$428,128 vs. first-year contractual IO debt service at 5.90% of ~$341,766. Estimated cash to borrower after $3.30M payoff, 0.75% origination fee, and $45,000 closing costs is roughly $2.404M. In the combined downside (EGI -5%, management rechecked, other OpEx held, sizing rate +100 bps to 7.25%, cap unchanged), stressed NOI before reserves is ~$503,252, NCF ~$492,452, and the binding DSCR-limited maximum loan is about $4.81M (LTV and debt yield limits are higher). Prepayment friction is 1% in years 1–2 with no stated penalty thereafter and no swap assumed.",
  "blocked": [
    "Requested downloadable XLSX underwriting workbook with live formulas (artifact creation not supported in this control).",
    "Requested concise financing memorandum as a PDF or native memo with PDF export (artifact creation not supported in this control)."
  ]
}
